def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n >= 99:
        return 'D'

    me = tuple(h[0] for h in history)
    op = tuple(h[1] for h in history)
    op_c = sum(1 for x in op if x == 'C')
    op_d = n - op_c
    w = 10 if n >= 10 else n
    rop_c = sum(1 for x in op[-w:] if x == 'C')
    rop_d = w - rop_c
    last_op = op[-1]
    last_me = me[-1]
    rounds_left = 100 - n

    recent_succ = 0
    recent_pun = 0
    start = n - 12
    if start < 0:
        start = 0
    for i in range(start, n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                recent_succ += 1
            else:
                recent_pun += 1

    tolerant = (recent_succ >= 2 and recent_pun == 0 and
                rop_c >= 6 and op_c > op_d)

    if op_c == 0:
        return 'D'
    if n >= 10 and rop_c == 0:
        return 'D'

    if op_d == 0:
        if last_me == 'D' and recent_succ == 0:
            if rounds_left <= 5:
                return 'D'
            return 'C'
        if recent_succ >= 1:
            return 'D'
        if n >= 90:
            return 'D' if rng.random() < 0.88 else 'C'
        if n >= 78:
            return 'D' if rng.random() < 0.55 else 'C'
        if n >= 50:
            return 'D' if rng.random() < 0.10 else 'C'
        if n >= 20:
            return 'D' if rng.random() < 0.015 else 'C'
        return 'C'

    if op_d >= op_c + 4 or (n >= 10 and rop_d >= 9):
        if last_op == 'D' and last_me == 'D' and rop_c >= 2:
            return 'C'
        if last_op == 'C' and rounds_left <= 15 and rop_c >= 3 and rng.random() < 0.15:
            return 'C'
        return 'D'

    if last_op == 'D':
        if last_me == 'D':
            if rop_c >= 3 or op_c > op_d + 2:
                if rop_d >= 8 and rop_c <= 1:
                    return 'D'
                return 'C'
            return 'D'

        if n >= 2 and me[-2] == 'D':
            if op_c > op_d + 2 and rop_d <= 2:
                return 'C'
            if rop_d >= 5:
                return 'D'
            return 'C' if op_c > op_d else 'D'

        if rop_d >= 4 or op_d > op_c:
            return 'D'

        if op_c > op_d + 2 and rop_d <= 1:
            return 'D' if rng.random() < 0.70 else 'C'

        if n >= 6 and rop_c >= 7:
            return 'C'

        return 'D'

    # last_op == 'C'
    if recent_succ >= 1 and recent_pun == 0 and rop_c >= 7 and op_c > op_d + 2:
        if last_me == 'D' or rounds_left <= 40 or rng.random() < 0.15:
            return 'D'

    if tolerant:
        if last_me == 'D':
            return 'D'
        if rounds_left <= 20:
            return 'D'

    if op_c >= n - max(2, n // 12):
        if last_me == 'D' and ((recent_succ >= 1 and recent_pun == 0) or rounds_left <= 2):
            return 'D'
        if rounds_left <= 5:
            return 'D' if rng.random() < 0.45 else 'C'
        if rounds_left <= 15 and rng.random() < 0.22:
            return 'D'
        if rounds_left <= 35 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if last_me == 'D':
        if rop_c >= 8 and recent_succ >= 2 and recent_pun == 0:
            return 'D'
        return 'C'

    if rounds_left <= 4 and rop_c >= 2 and op_c >= op_d:
        return 'D'

    if rng.random() < 0.003:
        return 'D'

    return 'C'
